using System;using System.IO;using System.Linq;using System.Drawing;using Musikbox;
class FormatTests{static void Main(string[] args){string root=args[1];Directory.CreateDirectory(root);string image=Path.Combine(root,"cover.png");using(var b=new Bitmap(32,32)){using(var g=Graphics.FromImage(b))g.Clear(Color.Purple);b.Save(image);}var song=MediaMetadata.Read(args[0]);song.Artwork=image;string tagged=Path.Combine(root,"input.mp3");MediaMetadata.WriteCopy(song,song.Album,tagged,()=>{});song=MediaMetadata.Read(tagged);foreach(string format in new[]{"MP3","FLAC","WAV","OGG","M4A","OPUS"}){string result=AudioConversion.Convert(new[]{song},root,format,192,false,"/usr/bin/ffmpeg",()=>{});string output=Directory.GetFiles(result).Single();var check=MediaMetadata.Read(output);if(check.Artist!=song.Artist||check.Album!=song.Album||check.Genre!=song.Genre||check.Duration<2.9)throw new Exception("Metadaten/Dauer: "+format);if(format!="WAV"&&MediaMetadata.Artwork(output)==null)throw new Exception("Cover fehlt: "+format);Console.WriteLine("OK "+format+" echte Konvertierung, Metadaten und Cover");}Console.WriteLine("BESTANDEN: sechs Zielformate; WAV-Metadaten, Cover bei allen uebrigen Formaten");}}
